    "httpMethod": "POST",
    "path": "/v1/payment_requests",
    "operationId": "createPaymentRequest",
    "summary": "Create a payment request",
    "description": "Create a payment request and get back the `checkout_url`, Relay's pay\npage for it. Relay creates one Stripe PaymentIntent on your\norganization's own connected Stripe account, as a direct charge (in\nsubscription mode, an incomplete Subscription whose first-period\nPaymentIntent is that one object): the money settles to your Stripe\naccount, you are the merchant of record, and Relay never holds the\nfunds. Relay takes a 5% fee on every payment, as a Stripe application\nfee (`application_fee_amount`); in subscription mode it is 5% of every\nperiod. The pay page and the Relay app's payment sheet both pay that\nsame PaymentIntent, so a person can never pay twice. Refunds and\ndisputes are handled in your own Stripe Dashboard; when you refund a\npayment, Relay returns the same share of its fee.\n\nA request is payable for 23 hours (`expires_at`); after that Relay\nstops the payment and the request moves to `expired`.\n\nSend the request to a person as a `payment` message part. Its status\nmoves only on Stripe's word: `payment.succeeded`, `payment.canceled`\nand `payment.expired` tell your agent, and every card that carries\nthe request changes in place.\n\nReturns 403 until your organization has connected Stripe in the Relay\nConsole and the account can accept charges. Stripe's own validation\n(currency, minimum amount, an unknown price, customer or coupon) comes\nback as 400 carrying Stripe's message. Returns 503 while payments are\nnot available on this server.\n",
    "definitions": [
      "export interface PaymentRequestCreateParams {\n  /** Payment mode: what to charge, in the currency's minor units. */\n  amount?: number;\n  /** Payment mode: a 3-letter ISO 4217 code, returned lowercase. */\n  currency?: string;\n  /** The card's title line and the checkout's product name. Trimmed; 1 to 32 characters. */\n  description: string;\n  category: PaymentCategory;\n  /** Up to 49 keys of your own; keys starting with `relay_` are reserved. */\n  metadata?: Record<string, string>;\n  /** Defaults to `payment`. */\n  mode?: PaymentMode;\n  /** Subscription mode: an active recurring Price on your connected Stripe account. */\n  price_id?: string;\n  /** Subscription mode: units of the price. Defaults to 1. */\n  quantity?: number;\n  /** An existing Customer on your connected Stripe account (`cus_...`). */\n  customer_id?: string;\n  discount?: PaymentDiscount;\n  /** Optional HTTPS product picture; Relay copies it into its own image store. */\n  image_url?: string;\n}",
      "export type PaymentCategory = \"physical_goods\" | \"digital_goods\" | \"donation\";",
      "export type PaymentMode = \"payment\" | \"subscription\";",
      "export interface PaymentDiscount {\n  /** The id of a coupon on your connected Stripe account. */\n  coupon?: string;\n  /** The id of a promotion code (`promo_...`), not the code a customer types. */\n  promotion_code?: string;\n  /** Your own name for the discount, stored and returned with the request. */\n  label?: string;\n}",
      "export interface PaymentRequestCreateOptions extends RequestOptions {\n  /** Reusing a key with the same body returns the first request (200); with a different body, 409. */\n  idempotencyKey?: string;\n}",
      "export interface RequestOptions {\n  signal?: AbortSignal;\n  timeout?: number;\n  maxRetries?: number;\n  headers?: HeadersInit;\n}",
      "export interface PaymentRequest {\n  id: UUID;\n  object: \"payment_request\";\n  status: PaymentStatus;\n  mode: PaymentMode;\n  /** What the person is charged at checkout, in minor units. */\n  amount: number;\n  /** Relay's 5% fee in minor units. */\n  application_fee_amount: number;\n  currency: string;\n  description: string;\n  category: PaymentCategory;\n  /** Relay's pay page for this request. Send it back unchanged in a `payment` part. */\n  checkout_url: string;\n  /** 23 hours after creation; the request then moves to `expired`. */\n  expires_at: string;\n  metadata: Record<string, string>;\n  image_url?: string;\n  price_id?: string;\n  quantity?: number;\n  interval?: PaymentRecurring[\"interval\"];\n  interval_count?: number;\n  discount?: PaymentDiscount;\n  stripe: PaymentRequestStripe;\n  /** Absent until the request succeeds. */\n  paid_at?: string;\n  created_at: string;\n  updated_at: string;\n}",
      "export type UUID = string;",
      "export type PaymentStatus = \"requested\" | \"succeeded\" | \"canceled\" | \"expired\";",
      "export interface PaymentRecurring {\n  interval: \"day\" | \"week\" | \"month\" | \"year\";\n  /** Intervals per renewal (3 with `month` is quarterly). */\n  interval_count: number;\n}",
      "export interface PaymentRequestStripe {\n  /** The one PaymentIntent the person pays (`pi_...`). */\n  payment_intent_id: string;\n  customer_id?: string;\n  /** Subscription mode (`sub_...`). */\n  subscription_id?: string;\n}"
    ],
